// Private diagnostic replay. The input text is generated by replay_model2_trace.py;
// no copyrighted capture, texture or raster is part of this program.
#include "gl_scene.h"
#include "gl_context.h"
#include "model2_scene.h"
#include <glad/gl.h>
#include <glm/gtc/matrix_transform.hpp>
#include <filesystem>
#include <fstream>
#include <iostream>

using namespace vcop2;
static std::vector<uint8_t> bytes(const std::filesystem::path& file) {
    std::ifstream in(file,std::ios::binary);if(!in)throw std::runtime_error("Cannot read "+file.string());
    return {std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>()};
}
static std::shared_ptr<NativeFrame> read_frame(const char* text,const std::filesystem::path& root) {
    auto f=std::make_shared<NativeFrame>();std::ifstream in(text);if(!in)throw std::runtime_error("Cannot read diagnostic geometry");
    size_t count;in>>f->sequence>>f->width>>f->height>>f->xoffset>>f->yoffset>>count;
    if(count>32768||f->width<1||f->height<1||f->width>2048||f->height>2048)throw std::runtime_error("Invalid diagnostic frame");
    f->polygons.resize(count);
    for(auto& p:f->polygons) {
        in>>p.count>>p.attr>>p.window>>p.sort>>p.luma>>p.lod>>p.object>>p.culled;
        if(p.count<3||p.count>4)throw std::runtime_error("Invalid diagnostic polygon");
        for(auto& h:p.header)in>>h;for(auto& h:p.focus)in>>h;for(auto& h:p.center)in>>h;for(auto& h:p.viewport)in>>h;
        for(unsigned i=0;i<p.count;i++){auto& v=p.vertices[i];in>>v.x>>v.y>>v.z>>v.u>>v.v;}
    }
    if(!in)throw std::runtime_error("Incomplete diagnostic geometry");
    std::ifstream camera(std::string(text)+".camera"),matrices(std::string(text)+".matrices"),culls(std::string(text)+".culls");
    if(camera)camera>>f->native_fov>>f->native_reference_fov;
    if(matrices)for(auto& p:f->polygons)for(auto& v:p.matrix)matrices>>v;
    if(culls)for(auto& p:f->polygons)culls>>p.cull_reasons;
    for(const auto* name:{"texture0","texture1","palette","colorxlat","luma","gamma"})f->blobs.push_back({name,bytes(root/(std::string(name)+".bin"))});
    for(const auto* name:{"background","foreground","native"}){
        auto raw=bytes(root/(std::string(name)+"-argb32.bin"));if(raw.size()!=size_t(f->width)*f->height*4)throw std::runtime_error("Incomplete native raster");
        auto& pixels=std::string(name)=="background"?f->background:std::string(name)=="foreground"?f->foreground:f->native;
        for(size_t i=0;i<raw.size();i+=4)pixels.push_back(raw[i]|(uint32_t(raw[i+1])<<8)|(uint32_t(raw[i+2])<<16)|(uint32_t(raw[i+3])<<24));
    }
    f->complete=true;return f;
}
static glm::mat4 projection(const NativeLens& l) {
    constexpr float n=.001f;return glm::frustum(float(-l.cx/l.fx*n),float((l.width-l.cx)/l.fx*n),float(-(l.height-l.cy)/l.fy*n),float(l.cy/l.fy*n),n,10000.f);
}
static std::vector<uint8_t> render(GLScene& scene,const NativeFrame& f,float eye) {
    glViewport(0,0,f.width,f.height);glClearColor(0,0,0,1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);
    auto vp=projection(presentation_lens(f))*glm::translate(glm::mat4(1),glm::vec3(-eye,0,0));
    scene.draw(vp,.02f,3.f);glFinish();std::vector<uint8_t> pixels(size_t(f.width)*f.height*4);
    glReadPixels(0,0,f.width,f.height,GL_RGBA,GL_UNSIGNED_BYTE,pixels.data());
    if(auto error=glGetError())throw std::runtime_error("GL replay error "+std::to_string(error));return pixels;
}
static void ppm(const std::filesystem::path& path,const NativeFrame& f,const std::vector<uint8_t>& pixels) {
    std::ofstream out(path,std::ios::binary);out<<"P6\n"<<f.width<<' '<<f.height<<"\n255\n";
    for(int y=f.height-1;y>=0;y--)for(int x=0;x<f.width;x++)out.write(reinterpret_cast<const char*>(pixels.data()+(size_t(y)*f.width+x)*4),3);
    if(!out)throw std::runtime_error("Cannot write replay raster");
}
int main(int argc,char** argv)try {
    if(argc!=4){std::cerr<<"usage: replay_model2_frames geometry.txt capture-directory output-prefix\n";return 2;}
    auto frame=read_frame(argv[1],argv[2]);GLContext context;
    std::cout<<"GL "<<glGetString(GL_VERSION)<<" / "<<glGetString(GL_RENDERER)<<'\n';
    GLuint fbo,color,depth;glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);
    glGenTextures(1,&color);glBindTexture(GL_TEXTURE_2D,color);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,frame->width,frame->height,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);
    glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,color,0);
    glGenRenderbuffers(1,&depth);glBindRenderbuffer(GL_RENDERBUFFER,depth);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH_COMPONENT24,frame->width,frame->height);
    glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depth);
    if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)throw std::runtime_error("Incomplete replay framebuffer");
    {GLScene scene;scene.prepare(frame);for(auto [name,eye]:{std::pair<const char*,float>{"neutral",0},{"left",-.032f},{"right",.032f}})
        ppm(std::string(argv[3])+"-"+name+".ppm",*frame,render(scene,*frame,eye));
        scene.prepare(frame,true);
        ppm(std::string(argv[3])+"-left-wide.ppm",*frame,render(scene,*frame,-.032f));
        ppm(std::string(argv[3])+"-right-wide.ppm",*frame,render(scene,*frame,.032f));}
    glDeleteFramebuffers(1,&fbo);glDeleteTextures(1,&color);glDeleteRenderbuffers(1,&depth);
    std::cout<<"Replayed "<<frame->polygons.size()<<" native polygons in three independent eye passes\n";
    return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
